-- Living Things (10 questions)
('q_bece_sci_2024_01', 'topic_bece_living', 'subj_bece_science', 'Which organ is responsible for pumping blood in the human body?', 'multiple_choice', '["A. Lungs", "B. Liver", "C. Heart", "D. Kidney"]', 'C', 'The heart pumps blood throughout the body.', 'easy', 1, 60),
('q_bece_sci_2024_02', 'topic_bece_living', 'subj_bece_science', 'Plants make their own food through a process called:', 'multiple_choice', '["A. Respiration", "B. Photosynthesis", "C. Digestion", "D. Excretion"]', 'B', 'Photosynthesis is the process by which plants make food using sunlight.', 'easy', 1, 60),
('q_bece_sci_2024_03', 'topic_bece_living', 'subj_bece_science', 'Which part of the plant absorbs water from the soil?', 'multiple_choice', '["A. Leaves", "B. Stem", "C. Roots", "D. Flowers"]', 'C', 'Roots absorb water and minerals from the soil.', 'easy', 1, 60),
('q_bece_sci_2024_04', 'topic_bece_living', 'subj_bece_science', 'The basic unit of life is the:', 'multiple_choice', '["A. organ", "B. tissue", "C. cell", "D. system"]', 'C', 'The cell is the smallest unit of life.', 'easy', 1, 60),
('q_bece_sci_2024_05', 'topic_bece_living', 'subj_bece_science', 'Which blood cells help fight disease?', 'multiple_choice', '["A. Red blood cells", "B. White blood cells", "C. Platelets", "D. Plasma"]', 'B', 'White blood cells protect the body against infections.', 'easy', 1, 60),
('q_bece_sci_2024_06', 'topic_bece_living', 'subj_bece_science', 'An organism that feeds on dead matter is called a:', 'multiple_choice', '["A. Producer", "B. Consumer", "C. Decomposer", "D. Herbivore"]', 'C', 'Decomposers break down dead organic matter.', 'medium', 1, 60),
('q_bece_sci_2024_07', 'topic_bece_living', 'subj_bece_science', 'The gas that plants take in during photosynthesis is:', 'multiple_choice', '["A. Oxygen", "B. Carbon dioxide", "C. Nitrogen", "D. Hydrogen"]', 'B', 'Plants absorb carbon dioxide and release oxygen during photosynthesis.', 'easy', 1, 60),
('q_bece_sci_2024_08', 'topic_bece_living', 'subj_bece_science', 'Which organ removes waste from the blood?', 'multiple_choice', '["A. Heart", "B. Lungs", "C. Kidneys", "D. Stomach"]', 'C', 'Kidneys filter waste from the blood to produce urine.', 'easy', 1, 60),
('q_bece_sci_2024_09', 'topic_bece_living', 'subj_bece_science', 'Amphibians can live:', 'multiple_choice', '["A. Only in water", "B. Only on land", "C. Both in water and on land", "D. Only in trees"]', 'C', 'Amphibians like frogs can survive in both water and land.', 'easy', 1, 60),
('q_bece_sci_2024_10', 'topic_bece_living', 'subj_bece_science', 'The process by which organisms produce offspring is called:', 'multiple_choice', '["A. Growth", "B. Reproduction", "C. Respiration", "D. Nutrition"]', 'B', 'Reproduction is the biological process of producing new organisms.', 'easy', 1, 60),

-- Matter and Energy (10 questions)
('q_bece_sci_2024_11', 'topic_bece_matter', 'subj_bece_science', 'Which state of matter has a definite shape and volume?', 'multiple_choice', '["A. Gas", "B. Liquid", "C. Solid", "D. Plasma"]', 'C', 'Solids have fixed shape and volume.', 'easy', 1, 60),
('q_bece_sci_2024_12', 'topic_bece_matter', 'subj_bece_science', 'The change from solid to liquid is called:', 'multiple_choice', '["A. Freezing", "B. Melting", "C. Evaporation", "D. Condensation"]', 'B', 'Melting is the process of solid becoming liquid.', 'easy', 1, 60),
('q_bece_sci_2024_13', 'topic_bece_matter', 'subj_bece_science', 'Which simple machine is a wheel with a groove for a rope?', 'multiple_choice', '["A. Lever", "B. Inclined plane", "C. Pulley", "D. Wedge"]', 'C', 'A pulley uses a wheel and rope to lift loads.', 'easy', 1, 60),
('q_bece_sci_2024_14', 'topic_bece_matter', 'subj_bece_science', 'Energy cannot be created or destroyed. This is the law of:', 'multiple_choice', '["A. Motion", "B. Conservation of energy", "C. Gravity", "D. Thermodynamics"]', 'B', 'The law of conservation of energy states energy is only transformed.', 'medium', 1, 90),
('q_bece_sci_2024_15', 'topic_bece_matter', 'subj_bece_science', 'The SI unit of force is:', 'multiple_choice', '["A. Joule", "B. Watt", "C. Newton", "D. Pascal"]', 'C', 'Force is measured in Newtons (N).', 'easy', 1, 60),
('q_bece_sci_2024_16', 'topic_bece_matter', 'subj_bece_science', 'A mixture of salt and water is called a:', 'multiple_choice', '["A. Suspension", "B. Colloid", "C. Solution", "D. Compound"]', 'C', 'When salt dissolves in water, it forms a solution.', 'easy', 1, 60),
('q_bece_sci_2024_17', 'topic_bece_matter', 'subj_bece_science', 'Sound travels fastest through:', 'multiple_choice', '["A. Air", "B. Water", "C. Solids", "D. Vacuum"]', 'C', 'Sound travels fastest through solids due to closely packed particles.', 'medium', 1, 60),
('q_bece_sci_2024_18', 'topic_bece_matter', 'subj_bece_science', 'Which type of energy is stored in food?', 'multiple_choice', '["A. Kinetic energy", "B. Sound energy", "C. Chemical energy", "D. Light energy"]', 'C', 'Food contains chemical energy that the body converts to other forms.', 'easy', 1, 60),
('q_bece_sci_2024_19', 'topic_bece_matter', 'subj_bece_science', 'The boiling point of water is:', 'multiple_choice', '["A. 0°C", "B. 50°C", "C. 100°C", "D. 212°C"]', 'C', 'Water boils at 100°C at standard atmospheric pressure.', 'easy', 1, 60),
('q_bece_sci_2024_20', 'topic_bece_matter', 'subj_bece_science', 'A lever is used to:', 'multiple_choice', '["A. Store energy", "B. Multiply force", "C. Create electricity", "D. Purify water"]', 'B', 'Levers help multiply force to lift heavy objects.', 'easy', 1, 60),

