('q_bece_sci_2024_21', 'topic_bece_environment', 'subj_bece_science', 'The protective layer in the atmosphere that blocks UV rays is:', 'multiple_choice', '["A. Oxygen layer", "B. Ozone layer", "C. Nitrogen layer", "D. Carbon layer"]', 'B', 'The ozone layer protects Earth from harmful UV radiation.', 'easy', 1, 60),
