('q_bece_sci_2024_24', 'topic_bece_environment', 'subj_bece_science', 'The main gas causing global warming is:', 'multiple_choice', '["A. Oxygen", "B. Carbon dioxide", "C. Nitrogen", "D. Helium"]', 'B', 'Carbon dioxide is a major greenhouse gas causing global warming.', 'easy', 1, 60),
('q_bece_sci_2024_25', 'topic_bece_environment', 'subj_bece_science', 'Which disease is caused by lack of iron?', 'multiple_choice', '["A. Rickets", "B. Scurvy", "C. Anaemia", "D. Goitre"]', 'C', 'Iron deficiency leads to anaemia (low red blood cells).', 'medium', 1, 60),
