('q_bece_sci_2024_28', 'topic_bece_environment', 'subj_bece_science', 'Which food group provides the most energy?', 'multiple_choice', '["A. Proteins", "B. Vitamins", "C. Carbohydrates", "D. Minerals"]', 'C', 'Carbohydrates are the main source of energy for the body.', 'easy', 1, 60),
